grid=[[0]*20 for _ in range(20)]
# Original 2 square
for r in range(2,9):
    for c in range(9,16): grid[r][c]=2
# Horizontal extensions, respecting same-row markers outside on each side
left_block={2,4,7}; right_block={3,8}
for r in range(2,9):
    if r not in left_block:
        for c in range(0,9): grid[r][c]=2
    if r not in right_block:
        for c in range(16,20): grid[r][c]=2
# Vertical extensions, respecting same-column markers above/below
for c in range(9,16):
    if c not in set():
        for r in range(0,2): grid[r][c]=2
    if c not in {9,13,15}:
        for r in range(9,20): grid[r][c]=2
# Restore 1 markers
for r,c in [(2,6),(3,19),(4,5),(7,1),(8,19),(12,9),(17,13),(19,15)]: grid[r][c]=1
print('\n'.join(' '.join(map(str,row)) for row in grid))
